        line = line.strip()
        if not line:
            continue
        try:
            a, b = map(float, line.split())
        except ValueError:
            continue

        for name, expression in formulas.items():
            try:
                value = ast.literal_eval(expression)
                if isinstance(value, (int, float)):
                    print(f"{name}={repr(value)}")
                else:
                    print(f"{name}={repr(eval(expression, {'a': a, 'b': b}))}")
            except (SyntaxError, ValueError):
                continue

if __name__ == "__main__":
    formulas = fetch_formulas()
    evaluate_formulas(formulas)
    sys.exit(0)

import sys
import hashlib
import requests
import defusedxml.ElementTree as ET
from defusedxml.common import EntitiesForbidden

def fetch_verified():
    if len(sys.argv) != 2:
        print("Usage: python fetch_verified.py <url>")
        return

    url = sys.argv[1]

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        print(f"Error fetching manifest: {e}")
        return

    try:
        root = ET.fromstring(response.content)
    except (ET.ParseError, EntitiesForbidden) as e:
        print(f"Error parsing XML: {e}")
        return

    file_url = root.find('file_url').text
    file_name = root.find('file_name').text
    hash_algorithm = root.find('hash_algorithm').text
    expected_hash = root.find('expected_hash').text

    try:
        file_response = requests.get(file_url, timeout=30)
        file_response.raise_for_status()
        file_bytes = file_response.content
    except requests.RequestException as e:
        print(f"Error fetching file: {e}")
        return

    try:
        hash_func = getattr(hashlib, hash_algorithm)()
    except AttributeError:
        print(f"Unsupported hash algorithm: {hash_algorithm}")
        return

    hash_func.update(file_bytes)
    computed_hash = hash_func.hexdigest()

    if computed_hash == expected_hash:
        try:
            with open(file_name, 'wb') as f:
                f.write(file_bytes)
            print("OK")
        except IOError as e:
            print(f"Error writing file: {e}")
    else:
        print("FAIL")

if __name__ == "__main__":
    fetch_verified()

import sys
import defusedxml.ElementTree as ET
import requests
import re
import ast

def parse_config(file_path):
    config = {}
    with open(file_path, 'r') as file:
        for line in file:
            line = line.strip()
            if line and not line.startswith('#'):
                key, value = line.split('=', 1)
                config[key.strip()] = value.strip()
    return config

def fetch_and_sum_prices(url):
    response = requests.get(url, timeout=10)
    root = ET.fromstring(response.content)
    prices = root.findall('.//price')
    return sum(float(price.text) for price in prices)

def evaluate_threshold(threshold):
    return ast.literal_eval(re.sub(r'(\d+\.\d+|\d+)', r'float(\1)', threshold))

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_stock.py <config_file>")
        sys.exit(1)

    config = parse_config(sys.argv[1])
    feed_url = config.get('feed_url')
    threshold = config.get('threshold')

    if not feed_url or not threshold:
        print("Error: Missing feed_url or threshold in config file")
        sys.exit(1)

    total_price = fetch_and_sum_prices(feed_url)
    threshold_value = evaluate_threshold(threshold)

    print("OK" if total_price > threshold_value else "LOW")

if __name__ == "__main__":
    main()

import os
import time
import json
import uuid
import requests
from datetime import datetime, timezone

def poll_health_endpoint():
    health_url = os.environ.get('HEALTH_URL')
    if not health_url:
        raise ValueError("HEALTH_URL environment variable is not set")

    while True:
        try:
            response = requests.get(health_url, timeout=10)
            response.raise_for_status()
            data = response.json()

            if 'service' in data and 'status' in data:
                log_entry = {
                    'timestamp': datetime.now(timezone.utc).isoformat(timespec='milliseconds') + 'Z',
                    'service': data['service'],
                    'status': data['status'],
                    'request_id': uuid.uuid4().hex
                }
            else:
                raise ValueError("Response JSON missing required fields")

        except Exception as e:
            log_entry = {
                'timestamp': datetime.now(timezone.utc).isoformat(timespec='milliseconds') + 'Z',
                'error': str(e)
            }

        with open('health.log', 'a') as log_file:
            log_file.write(json.dumps(log_entry) + '\n')

        time.sleep(10)

if __name__ == "__main__":
    poll_health_endpoint()

import sys
import urllib.request
import json
import re
import ast

def fetch_json(url):
    # Ensure the URL uses a permitted scheme
    if not url.startswith(('http://', 'https://')):
        raise ValueError("Unsupported URL scheme")
    with urllib.request.urlopen(url) as response:
        return json.loads(response.read().decode())

def evaluate_expression(expression, context):
    try:
        # Use ast.literal_eval for safer evaluation
        return str(ast.literal_eval(expression))
    except (ValueError, SyntaxError):
        return ''

def render_template(template, context):
    pattern = re.compile(r'\{\{(.+?)\}\}')
    return pattern.sub(lambda m: evaluate_expression(m.group(1), context), template)

def main():
    if len(sys.argv) != 3:
        print("Usage: python report_renderer.py <url> <template_file>")
        sys.exit(1)

    url, template_file = sys.argv[1], sys.argv[2]

    try:
        json_data = fetch_json(url)
        with open(template_file, 'r') as file:
            template = file.read()
        rendered_html = render_template(template, json_data)
        print(rendered_html)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import defusedxml.ElementTree as ET
import ast

def evaluate_formula(formula, context):
    try:
        return ast.literal_eval(formula)
    except (ValueError, SyntaxError) as e:
        return f"Error: {e}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python formula_report.py report.xml")
        return

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError:
        print("Error: Could not parse XML file.")
        return
    except FileNotFoundError:
        print("Error: XML file not found.")
        return

    context = {}
    print("<table>")
    print("<tr><th>field</th><th>value</th></tr>")

    for field in root.findall('field'):
        name = field.get('name')
        formula = field.get('formula')
        if name and formula:
            value = evaluate_formula(formula, context)
            context[name] = value
            print(f"<tr><td>{name}</td><td>{value}</td></tr>")

    print("</table>")

if __name__ == "__main__":
    main()

import sys
import re
import time
import ast
import operator

def evaluate_expression(expression):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos
    }

    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return allowed_operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            return allowed_operators[type(node.op)](operand)
        else:
            raise ValueError("Unsupported operation")

    tree = ast.parse(expression, mode='eval')
    return eval_node(tree.body)

def process_line(line, line_number):
    pattern = r'\{\{(.+?)\}\}'
    matches = re.finditer(pattern, line)
    for match in matches:
        expression = match.group(1).strip()
        try:
            result = evaluate_expression(expression)
            line = line.replace(match.group(0), str(result))
        except Exception as e:
            sys.stderr.write(f"line {line_number}: {str(e)}\n")
            return None
    return line

def main():
    error_count = 0
    line_number = 0

    for line in sys.stdin:
        line_number += 1
        if line_number > 1:
            time.sleep(0.2)

        processed_line = process_line(line, line_number)
        if processed_line is not None:
            sys.stdout.write(processed_line)
        else:
            sys.stdout.write(line)
            error_count += 1

    if error_count > 0:
        sys.stderr.write(f"errors: {error_count}\n")

if __name__ == "__main__":
    main()
